SINA_SMART["histo1-bone"] = {"lecture":"histo1-bone","title":"Bone","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-bone:e0","text":"Bone: periosteum outside, endosteum inside; stores calcium, houses marrow.","topic":"Bone tissue and its matrix","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e1","text":"Matrix = collagen I (steel) + hydroxyapatite (cement).","topic":"Bone tissue and its matrix","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e2","text":"Osteoblast makes osteoid → becomes osteocyte in a lacuna, processes in canaliculi.","topic":"Bone cells, periosteum and endosteum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e3","text":"Osteoclast: multinucleated, from monocytes, Howship's lacuna, ruffled border.","topic":"Bone cells, periosteum and endosteum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e4","text":"Periosteum: outer fibrous + inner osteogenic; Sharpey's fibres.","topic":"Bone cells, periosteum and endosteum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e5","text":"Primary (woven) bone first, replaced by secondary (lamellar) bone.","topic":"Types of bone","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e6","text":"Osteon: Haversian canal + concentric lamellae + cement line; Volkmann's canals transverse.","topic":"Types of bone","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e7","text":"Intramembranous: flat skull bones; endochondral: cartilage model (long bones).","topic":"Ossification and growth","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e8","text":"Growth plate zones: reserve, proliferative, hypertrophic, calcification, ossification.","topic":"Ossification and growth","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-bone:e9","text":"Vit D/Ca: rickets, osteomalacia; vit C: collagen; vit A excess: early plate closure.","topic":"Ossification and growth","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"b8osri":"a","oixux5":"a","leaj4n":"a","13pai2a":"a","1atiam4":"a","1jgt0o0":"a","5pt6x3":"a","l4jn71":"a","1f2uxzr":"a","1r97pll":"a","xi453k":"a","mgng5p":"a","1rsezzd":"a","axilar":"a","d963w2":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-bone:e0":{"s":0,"u":["Bone: periosteum outside, endosteum inside; stores calcium, houses marrow.","It is covered by periosteum outside and endosteum inside."],"dp":[]},"histo1-bone:e1":{"s":0,"u":["Matrix = collagen I (steel) + hydroxyapatite (cement).","The matrix is like reinforced concrete : collagen fibres are the steel bars and hydroxyapatite the cement.","Inorganic part : mainly calcium and phosphate as hydroxyapatite crystals bound to collagen, with some bicarbonate, potassium, magnesium and citrate."],"dp":[]},"histo1-bone:e2":{"s":1,"u":["Osteoblast makes osteoid → becomes osteocyte in a lacuna, processes in canaliculi.","Osteoblasts : on bone surfaces and around vessels; they synthesise the organic matrix (osteoid) and start mineralisation; once surrounded by matrix they become osteocytes , which sit in lacunae , extend processes through canaliculi to exchange nutrients, and maintain the matrix ."],"dp":[]},"histo1-bone:e3":{"s":1,"u":["Osteoclast: multinucleated, from monocytes, Howship's lacuna, ruffled border.","Osteoclasts : large multinucleated cells from blood monocytes , lying in Howship's lacunae ; their ruffled border releases acid and enzymes to resorb bone."],"dp":[]},"histo1-bone:e4":{"s":1,"u":["Periosteum: outer fibrous + inner osteogenic; Sharpey's fibres.","Periosteum : outer dense CT and inner loose CT with osteogenic cells and osteoblasts; anchored by Sharpey's fibres ; functions: nutrition, growth in girth, repair.","Osteoprogenitor cells : stem cells from mesenchyme in the inner periosteum and endosteum."],"dp":[]},"histo1-bone:e5":{"s":2,"u":["Primary (woven) bone first, replaced by secondary (lamellar) bone.","By maturity: primary (woven) bone , the first bone in development and fracture repair, with irregular collagen, many cells and less mineral, later replaced except at cranial sutures and tooth sockets; and secondary (lamellar) bone , mature bone with collagen in organised lamellae."],"dp":[{"h":"Why a fracture passes through woven bone","t":"After a fracture, a haematoma forms, then a soft callus of fibrocartilage and a hard callus of woven (primary) bone , laid down quickly by osteoblasts with collagen in irregular arrays. It bridges the gap within weeks but is mechanically weak. Over the following months osteoclasts and osteoblasts remodel it into lamellar bone organised into osteons along the lines of stress. That is why a healed bone looks thickened on an X-ray at first and why loading, not rest alone, guides the final shape. Source: the lecture's primary vs secondary bone and the fracture slide."}]},"histo1-bone:e6":{"s":2,"u":["Osteon: Haversian canal + concentric lamellae + cement line; Volkmann's canals transverse.","Compact bone is built of osteons : concentric lamellae around a Haversian canal (vessels, nerves), with osteocytes whose canaliculi radiate to the canal and a cement line around each osteon.","Volkmann's canals run transversely, linking canals to each other and to the marrow."],"dp":[]},"histo1-bone:e7":{"s":3,"u":["Intramembranous: flat skull bones; endochondral: cartilage model (long bones).","Intramembranous ossification : mesenchymal cells become osteoblasts that lay down osteoid and calcify it (alkaline phosphatase), trapping themselves as osteocytes; flat bones of the skull vault (the occipital, temporal and sphenoid are partly endochondral).","Endochondral ossification : a hyaline cartilage model is laid down; the perichondrium becomes periosteum as a vascular bud invades; growth in length at the epiphyseal plates; growth in diameter by periosteal deposition with osteoclastic enlargement of the marrow cavity."],"dp":[]},"histo1-bone:e8":{"s":3,"u":["Growth plate zones: reserve, proliferative, hypertrophic, calcification, ossification.","Zones of the growth plate, from the epiphysis: reserve (quiet), proliferative (chondrocytes in columns: the main source of lengthening), maturation / hypertrophy (large cells, alkaline phosphatase), calcification (matrix calcifies, chondrocytes die) and ossification (osteoblasts from the vascular bud lay bone on the calcified spicules).","Endochondral ossification : a hyaline cartilage model is laid down; the perichondrium becomes periosteum as a vascular bud invades; growth in length at the epiphyseal plates; growth in diameter by periosteal deposition with osteoclastic enlargement of the marrow cavity."],"dp":[]},"histo1-bone:e9":{"s":3,"u":["Vit D/Ca: rickets, osteomalacia; vit C: collagen; vit A excess: early plate closure.","Factors affecting bone: protein deficiency; calcium deficiency and vitamin D deficiency (poor mineralisation: rickets in children, osteomalacia in adults); vitamin A deficiency (poor growth) or excess (early closure of growth plates); vitamin C deficiency (defective collagen)."],"dp":[]}},"meta":{"b8osri":{"a":"recall","vg":"histo1-bone:e5/recall/1"},"oixux5":{"a":"recall","vg":"histo1-bone:e5/recall/2"},"leaj4n":{"a":"recall","vg":"histo1-bone:e2/recall/1"},"13pai2a":{"a":"recall","vg":"histo1-bone:e2/recall/2"},"1atiam4":{"a":"recall","vg":"histo1-bone:e3/recall/1"},"1jgt0o0":{"a":"recall","vg":"histo1-bone:e3/recall/2"},"5pt6x3":{"a":"recall","vg":"histo1-bone:e4/recall/1"},"l4jn71":{"a":"recall","vg":"histo1-bone:e6/recall/1"},"1f2uxzr":{"a":"recall","vg":"histo1-bone:e6/recall/2"},"1r97pll":{"a":"recall","vg":"histo1-bone:e5/recall/3"},"xi453k":{"a":"recall","vg":"histo1-bone:e7/recall/1"},"mgng5p":{"a":"recall","vg":"histo1-bone:e8/recall/1"},"1rsezzd":{"a":"recall","vg":"histo1-bone:e8/recall/2"},"axilar":{"a":"recall","vg":"histo1-bone:e9/recall/1"},"d963w2":{"a":"relationship","vg":"histo1-bone:e9/relationship/1"}},"explRev":"17d08185de72"};
